import{_ as o,o as e,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Code Walkthroughs: Crimson","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: Crimson","date":"2024-03-06T00:00:00.000Z","updated":"2024-03-07T00:00:00.000Z","tags":["Ceph","Distributed Storage","CRUSH Algorithm","High Availability","Scalability","Object Storage","Block Storage","File System Storage","Consistency","Decentralization","Performance","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","Authentication","Authorization","Encryption","Erasure Coding","Replication","Snapshots","Clones","Thin Provisioning","iSCSI","Fibre Channel","NFS","CIFS","POSIX","Monitoring","Dashboard","Management","Orchestration","Automation","Integration","Containerization","Kubernetes","Docker","Virtualization","Cloud Computing","AWS","Azure","Google Cloud","Hybrid Cloud","Multi","cloud","Storage Cluster","Node","Disk","SSD","HDD","JBOD","SAN","NAS","Network","Topology","Failure Domain","Recovery","Resilience","Load Balancing","Caching","Compression","Deduplication","Tiering","Performance Tuning","Benchmarking","Testing","Validation"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Code_Walkthroughs_-_Crimson.md","filePath":"posts/2024/Ceph_Code_Walkthroughs_-_Crimson.md","lastUpdated":1780459816000}'),t={name:"posts/2024/Ceph_Code_Walkthroughs_-_Crimson.md"};function r(n,i,s,u,h,d){return e(),l("div",null,[...i[0]||(i[0]=[a('<h3 id="改进的中文总结" tabindex="-1">改进的中文总结 <a class="header-anchor" href="#改进的中文总结" aria-label="Permalink to &quot;改进的中文总结&quot;">​</a></h3><p>Ceph 代码分析会议 &quot;Crimson&quot; 主要讨论了Ceph存储系统中Crimson代码与经典代码的差异，特别是使用seastar框架的情况。以下是会议的关键细节和讨论要点：</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>主题</strong>: 分析Crimson代码与经典代码的差异，特别是使用seastar框架。</li><li><strong>参与者</strong>: Ceph分布式存储研发人员。</li><li><strong>时间/地点</strong>: 未提供具体时间与地点，为线上视频会议。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>代码比较</strong>：</p><ul><li>经典代码为同步代码，处理请求简单直接。</li><li>Crimson代码采用seastar框架，使用Futures和Continuation。</li><li>Continuation为C++ Lambda表达式，用于在Future就绪或赋值时调用。</li></ul></li><li><p><strong>指针捕获</strong>：</p><ul><li>讨论在Lambda表达式中捕获<code>this</code>指针的安全性，建议避免捕获<code>con</code>和<code>request</code>以防生命周期问题。</li></ul></li><li><p><strong>消息处理</strong>：</p><ul><li>介绍messenger组件，作为Ceph通信层，处理如mosd_op等不同类型的消息。</li><li>mosd_op代表OSD操作，是实际的RADOS操作，包含对象ID和操作（如删除、写入等）。</li></ul></li><li><p><strong>对象上下文</strong>：</p><ul><li>对象上下文用于跟踪对象的修改状态，是一个缓存数据结构。</li><li>讨论了获取对象上下文的逻辑，包括从缓存中获取或从后端加载。</li></ul></li><li><p><strong>代码目录结构</strong>：</p><ul><li>Crimson代码主要位于Crimson目录中，是经典OSD的替代品。</li><li>讨论了Crimson代码中使用的一些特殊宏和适配问题。</li></ul></li><li><p><strong>客户端请求管道</strong>：</p><ul><li>介绍了Crimson中的客户端请求管道，包括等待地图阶段、活动等待阶段等。</li><li>强调了处理请求时需要满足的依赖条件，如OSD地图版本匹配。</li></ul></li><li><p><strong>错误处理</strong>：</p><ul><li>讨论了使用erator处理非严重错误的情况，确保程序在遇到错误时不会崩溃。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>确认了在Crimson代码中使用seastar框架的必要性和优势。</li><li>确定了处理请求时需要满足的依赖条件，并讨论了如何处理不满足的情况。</li><li>讨论了错误处理的策略，特别是使用erator来处理非严重错误。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化Crimson代码，特别是在错误处理和依赖条件满足方面的逻辑。</li><li>深入研究seastar框架的使用，确保代码的高效和稳定。</li><li>定期审查和更新代码，以保持与Ceph其他部分的兼容性和一致性。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到了一些技术细节和代码示例，对于深入理解Crimson代码的实现非常重要。</li><li>会议强调了代码的可维护性和错误处理策略，这些都是确保系统稳定运行的关键因素。</li></ul>',12)])])}const C=o(t,[["render",r]]);export{c as __pageData,C as default};
